Uma colega escreveu a `situacaoDoPrazo` com a guarda depois do `diasAte`:

```javascript
export function situacaoDoPrazo(prazo, hoje) {
  const dias = diasAte(prazo, hoje);
  if (prazo === null) {
    return 'sem-prazo';
  }
  if (dias < 0) {
    return 'atrasada';
  } else if (dias === 0) {
    return 'vence-hoje';
  } else {
    return 'em-dia';
  }
}
```

