```javascript
export function proximoPrazo(prazo, frequencia, hoje) {
  const dias = frequencia === 'diaria' ? 1 : 7;
  let novo = somarDias(prazo, dias);
  while (diasAte(novo, hoje) <= 0) {
    novo = somarDias(novo, dias);
  }
  return novo;
}
